func (q *Queries) OverrideRefs(ctx context.Context, arg OverrideRefsParams) ([]WeaveOverrideRefsArchive, error) {
	rows, err := q.db.Query(ctx, overrideRefs, arg.ProjectID, arg.Version, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WeaveOverrideRefsArchive{}
	for rows.Next() {
		var i WeaveOverrideRefsArchive
		if err := rows.Scan(
			&i.OverrideID,
			&i.RefType,
			&i.TargetID,
			&i.SemanticID,
			&i.Position,
			&i.ProjectID,
			&i.VersionNumber,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
